<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class FormalReportController extends Controller{
 private function p(Request $r){$p=$r->attributes->get('academic_period');abort_if(!$p,404);return $p;}
 private function students($pid,$gid){$q=DB::table('student_group_memberships as m')->join('students as s','s.id','=','m.student_id')->where('m.academic_period_id',$pid)->where('m.study_group_id',$gid)->where('m.status','active');return $q->exists()?$q->select('s.*')->orderBy('s.last_name')->get():DB::table('students')->where('current_group_id',$gid)->where('status','active')->orderBy('last_name')->get();}
 public function cover(Request $r,$group){$p=$this->p($r);$g=DB::table('study_groups')->find($group);abort_if(!$g,404);$curator=DB::table('teachers')->where('id',$g->curator_teacher_id)->first();return view('reports.formal.cover',compact('p','g','curator'));}
 public function attestation(Request $r,$group,$subject){$p=$this->p($r);$g=DB::table('study_groups')->find($group);$sub=DB::table('subjects')->find($subject);abort_if(!$g||!$sub,404);$students=$this->students($p->id,$group);$results=DB::table('semester_results')->where('academic_period_id',$p->id)->where('subject_id',$subject)->whereIn('student_id',$students->pluck('id'))->pluck('value','student_id');return view('reports.formal.attestation',compact('p','g','sub','students','results'));}
 public function summary(Request $r,$group){$p=$this->p($r);$g=DB::table('study_groups')->find($group);abort_if(!$g,404);$students=$this->students($p->id,$group);$subjects=DB::table('lesson_occurrences as l')->join('subjects as s','s.id','=','l.subject_id')->where('l.academic_period_id',$p->id)->where('l.study_group_id',$group)->select('s.id','s.name')->distinct()->orderBy('s.name')->get();$results=DB::table('semester_results')->where('academic_period_id',$p->id)->whereIn('student_id',$students->pluck('id'))->whereIn('subject_id',$subjects->pluck('id'))->get()->keyBy(fn($x)=>$x->student_id.'-'.$x->subject_id);return view('reports.formal.summary',compact('p','g','students','subjects','results'));}
 public function student(Request $r,$student){$p=$this->p($r);$s=DB::table('students')->find($student);abort_if(!$s,404);$m=DB::table('student_group_memberships')->where('student_id',$student)->where('academic_period_id',$p->id)->first();$gid=$m?->study_group_id??$s->current_group_id;$g=DB::table('study_groups')->find($gid);$subjects=DB::table('lesson_occurrences as l')->join('subjects as x','x.id','=','l.subject_id')->where('l.academic_period_id',$p->id)->where('l.study_group_id',$gid)->select('x.id','x.name')->distinct()->orderBy('x.name')->get();foreach($subjects as $x){$x->avg=DB::table('grade_records as gr')->join('lesson_occurrences as l','l.id','=','gr.lesson_occurrence_id')->where('gr.student_id',$student)->where('l.academic_period_id',$p->id)->where('l.subject_id',$x->id)->whereIn('gr.value',['2','3','4','5'])->avg(DB::raw('CAST(gr.value AS REAL)'));$x->result=DB::table('semester_results')->where(['academic_period_id'=>$p->id,'student_id'=>$student,'subject_id'=>$x->id])->value('value');}return view('reports.formal.student',compact('p','s','g','subjects'));}
 public function attendance(Request $r,$group){$p=$this->p($r);$g=DB::table('study_groups')->find($group);abort_if(!$g,404);$month=$r->input('month',now()->format('Y-m'));abort_unless(preg_match('/^\d{4}-\d{2}$/',$month),422);$from=$month.'-01';$to=date('Y-m-t',strtotime($from));$students=$this->students($p->id,$group);foreach($students as $s){$q=DB::table('attendance_records as a')->join('lesson_occurrences as l','l.id','=','a.lesson_occurrence_id')->where('a.student_id',$s->id)->where('l.academic_period_id',$p->id)->where('l.study_group_id',$group)->whereBetween('l.lesson_date',[$from,$to]);foreach(['present','absent','sick','excused','late'] as $st)$s->{$st}=(clone $q)->where('a.status',$st)->count();}return view('reports.formal.attendance',compact('p','g','students','month'));}
}